import java.util.Scanner;

public class Main {
    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        int total = sc.nextInt();
        int max_k = sc.nextInt();
        double[] values = new double[total];
        for (int i = 0; i < total; i++) {
            values[i] = sc.nextDouble();
        }
        int zero_count = 0;
        for (double v : values) {
            if (v < 1e-10) zero_count++;
        }
        max_k = Math.min(total - zero_count, max_k);
        int size = 1 << total;
        double[] probability = new double[size];
        double[] answer = new double[total];
        probability[0] = 1.0;
        for (int mask = 1; mask < size; mask++) {
            double sum_of_a = 0.0;
            boolean is_valid = true;
            int selected_bits = 0;
            for (int i = 0; i < total; i++) {
                if ((mask & (1 << i)) != 0) {
                    sum_of_a += values[i];
                    if (values[i] < 1e-10) is_valid = false;
                    selected_bits++;
                }
            }
            if (!is_valid) {
                probability[mask] = 0.0;
                continue;
            }
            double total_prob = 0.0;
            for (int i = 0; i < total; i++) {
                if ((mask & (1 << i)) != 0) {
                    double denom = 1.0 - sum_of_a + values[i];
                    total_prob += (values[i] / denom) * probability[mask ^ (1 << i)];
                }
            }
            probability[mask] = total_prob;
            if (selected_bits == max_k) {
                for (int i = 0; i < total; i++) {
                    if ((mask & (1 << i)) != 0) {
                        answer[i] += probability[mask];
                    }
                }
            }
        }
        for (int i = 0; i < total; i++) {
            System.out.printf("%.10f%c", answer[i], (i == total - 1) ? '\n' : ' ');
        }
        sc.close();
    }
}
